package seed

import (
	"bufio"
	"path/filepath"
	"strings"
)

type Change struct {
	Path        string
	Description string
}

type CompletionReport struct {
	Status        string
	Changes       []Change
	Decisions     []string
	DeadEnds      []string
	Findings      []string
	ProjectName   string
	WorkOrderName string
}

func ParseCompletionReport(content string) (*CompletionReport, error) {
	return parseCompletionReportWithPath(content, "")
}

func parseCompletionReportWithPath(content string, path string) (*CompletionReport, error) {
	report := &CompletionReport{}

	// If we have a path, we can try to derive ProjectName and WorkOrderName
	// Path pattern: .../pr-07-v2-storage/wo6-seeding/WORKORDER.md
	if path != "" {
		dir := filepath.Dir(path)
		report.WorkOrderName = filepath.Base(dir)
		report.ProjectName = filepath.Base(filepath.Dir(dir))
	}

	lines := strings.Split(content, "\n")

	inCompletionReport := false
	currentSection := ""

	for _, line := range lines {
		trimLine := strings.TrimSpace(line)

		if strings.HasPrefix(trimLine, "## Completion Report") {
			inCompletionReport = true
			continue
		}

		if !inCompletionReport {
			continue
		}

		if strings.HasPrefix(trimLine, "## ") && currentSection != "" && !strings.HasPrefix(trimLine, "## Completion Report") {
			// A new ## section means we exited Completion Report
			inCompletionReport = false
			break
		}

		if strings.HasPrefix(trimLine, "### ") {
			currentSection = strings.TrimPrefix(trimLine, "### ")
			continue
		}

		if trimLine == "" || trimLine == "(none)" {
			continue
		}

		switch currentSection {
		case "Status":
			report.Status = trimLine
		case "Changes Made":
			if strings.HasPrefix(trimLine, "- ") {
				item := strings.TrimPrefix(trimLine, "- ")
				// Format: `path/to/file` — description
				// or `path/to/file` - description
				// or `path/to/file`: description

				var pathPart, descPart string
				if idx := strings.Index(item, " — "); idx != -1 {
					pathPart = item[:idx]
					descPart = item[idx+len(" — "):]
				} else if idx := strings.Index(item, " - "); idx != -1 {
					pathPart = item[:idx]
					descPart = item[idx+len(" - "):]
				} else {
					pathPart = item
					descPart = ""
				}

				pathPart = strings.Trim(pathPart, "` ")
				descPart = strings.TrimSpace(descPart)

				report.Changes = append(report.Changes, Change{
					Path:        pathPart,
					Description: descPart,
				})
			}
		case "Decisions Made":
			if strings.HasPrefix(trimLine, "- ") {
				report.Decisions = append(report.Decisions, strings.TrimPrefix(trimLine, "- "))
			}
		case "Dead Ends & Warnings":
			if strings.HasPrefix(trimLine, "- ") {
				report.DeadEnds = append(report.DeadEnds, strings.TrimPrefix(trimLine, "- "))
			}
		case "Out-of-Scope Findings":
			if strings.HasPrefix(trimLine, "- ") {
				report.Findings = append(report.Findings, strings.TrimPrefix(trimLine, "- "))
			}
		}
	}

	if !inCompletionReport && report.Status == "" && len(report.Changes) == 0 && len(report.Decisions) == 0 {
		return nil, nil // No completion report found
	}

	return report, nil
}

package seed

import (
	"time"

	"github.com/cblabs-org/repo-memory-plugin/internal/core/config"
	"github.com/cblabs-org/repo-memory-plugin/internal/core/dossiers"
	"github.com/cblabs-org/repo-memory-plugin/internal/core/ops"
)

func ReportToOps(report *CompletionReport, resolver *config.ScopeResolver) []ops.Op {
	var result []ops.Op

	if report == nil {
		return result
	}

	var anchors []string
	for _, c := range report.Changes {
		anchors = append(anchors, c.Path)
	}

	dossierScope := resolver.ResolveScope(anchors, nil)
	now := time.Now()

	for _, dec := range report.Decisions {
		result = append(result, ops.Op{
			Type:         ops.OpAdd,
			EntryID:      ops.NewEntryID("dec"),
			DossierScope: dossierScope,
			Timestamp:    now,
			Source:       ops.SourceSeed,
			Fields: map[string]any{
				"type":    string(dossiers.EntryTypeDecision),
				"text":    dec,
				"anchors": anchors,
			},
		})
	}

	for _, de := range report.DeadEnds {
		result = append(result, ops.Op{
			Type:         ops.OpAdd,
			EntryID:      ops.NewEntryID("rul"),
			DossierScope: dossierScope,
			Timestamp:    now,
			Source:       ops.SourceSeed,
			Fields: map[string]any{
				"type":    string(dossiers.EntryTypeRuledOut),
				"text":    de,
				"anchors": anchors,
			},
		})
	}

	for _, finding := range report.Findings {
		result = append(result, ops.Op{
			Type:         ops.OpAdd,
			EntryID:      ops.NewEntryID("issue"),
			DossierScope: dossierScope,
			Timestamp:    now,
			Source:       ops.SourceSeed,
			Fields: map[string]any{
				"type":    string(dossiers.EntryTypeOpenIssue),
				"text":    finding,
				"anchors": anchors,
			},
		})
	}

	return result
}

package seed

import (
	"fmt"
	"os"
	"os/exec"
	"path/filepath"
	"strings"

	"github.com/cblabs-org/repo-memory-plugin/internal/core/config"
	"github.com/cblabs-org/repo-memory-plugin/internal/core/ops"
)

func ScanWorkorders(paDir string) ([]string, error) {
	var files []string
	err := filepath.Walk(paDir, func(path string, info os.FileInfo, err error) error {
		if err != nil {
			// Skip files/dirs we don't have access to
			if os.IsNotExist(err) || os.IsPermission(err) {
				return nil
			}
			return err
		}
		if !info.IsDir() && filepath.Base(path) == "WORKORDER.md" {
			content, err := os.ReadFile(path)
			if err != nil {
				return err
			}
			if strings.Contains(string(content), "## Completion Report") {
				files = append(files, path)
			}
		}
		return nil
	})
	return files, err
}

func SeedFromWorkorders(paDir string, opsWriter *ops.Writer, resolver *config.ScopeResolver) error {
	return SeedWithTimeCut(paDir, opsWriter, resolver, "")
}

func SeedWithTimeCut(paDir string, opsWriter *ops.Writer, resolver *config.ScopeResolver, beforeCommit string) error {
	files, err := ScanWorkorders(paDir)
	if err != nil {
		return err
	}

	seededOps := 0
	workordersSeeded := 0

	for _, path := range files {
		if beforeCommit != "" {
			// Use git to check if the workorder file existed at the given commit
			cmd := exec.Command("git", "show", fmt.Sprintf("%s:%s", beforeCommit, path))
			if err := cmd.Run(); err != nil {
				// file didn't exist at that commit or other error, skip
				continue
			}
		}

		content, err := os.ReadFile(path)
		if err != nil {
			return err
		}

		report, err := parseCompletionReportWithPath(string(content), path)
		if err != nil || report == nil {
			continue
		}

		newOps := ReportToOps(report, resolver)
		if len(newOps) > 0 {
			if opsWriter != nil {
				if err := opsWriter.WriteBatch(newOps); err != nil {
					return err
				}
			}
			seededOps += len(newOps)
			workordersSeeded++
		}
	}

	fmt.Printf("Seeded %d entries from %d workorders\n", seededOps, workordersSeeded)
	return nil
}

